async () => {
const g=document.querySelector('vaadin-grid');
const seen=new Map();
const collect=()=>{g.shadowRoot?.querySelectorAll('tr');
 g._getVisibleRows? 0:0;
 const rows=[...g.querySelectorAll('vaadin-grid-cell-content')].map(c=>c.textContent.trim());
 for(let i=0;i+4<rows.length;i+=5){}
 return rows;};
let last=-1;
for(let i=0;i<200;i++){
 const cells=[...g.querySelectorAll('vaadin-grid-cell-content')].map(c=>c.textContent.trim());
 // body cells after 5 headers
 for(let j=0;j<cells.length;j++){}
 const trs=[...g.shadowRoot.querySelectorAll('tbody tr')];
 for(const tr of trs){const t=[...tr.querySelectorAll('td')].map(td=>{const s=td.querySelector('slot');return s?s.assignedNodes()[0]?.textContent.trim():''});seen.set(t[2],t);}
 g.scrollTop+=300;
 await new Promise(r=>setTimeout(r,150));
 if(g.scrollTop===last)break;last=g.scrollTop;
}
const all=[...seen.values()];
const l=all.filter(t=>t[4]&&t[4].startsWith('Linens'));
return {total:all.length,linens:l.length,nc:l.filter(t=>t[3]==='Not contacted').length,rows:l.map(t=>t.join('|'))};
}

